using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
[InitializeOnLoad]public static class CoastalTerrainBuild{
const string Dir="Assets/Scenes/Oasis/CoastalTerrain";static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static List<Vector2> hull;static float cutZ;static Dictionary<Vector2Int,float> roads=new Dictionary<Vector2Int,float>();
static T Field<T>(object o,string n)=>(T)o.GetType().GetField(n).GetValue(o);static object Read(Mesh m)=>typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{m});
static CoastalTerrainBuild(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalTerrainBuild.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("CoastalTerrainBuild.request");Run();}
static float Cross(Vector2 a,Vector2 b,Vector2 c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
static List<Vector2> Hull(IEnumerable<Vector2> points){var p=points.Distinct().OrderBy(v=>v.x).ThenBy(v=>v.y).ToArray();var h=new List<Vector2>();foreach(var q in p){while(h.Count>=2&&Cross(h[h.Count-2],h.Last(),q)<=0)h.RemoveAt(h.Count-1);h.Add(q);}int lower=h.Count;for(int i=p.Length-2;i>=0;i--){while(h.Count>lower&&Cross(h[h.Count-2],h.Last(),p[i])<=0)h.RemoveAt(h.Count-1);h.Add(p[i]);}h.RemoveAt(h.Count-1);return h;}
static bool Inside(Vector2 p){for(int i=0;i<hull.Count;i++)if(Cross(hull[i],hull[(i+1)%hull.Count],p)<-.01f)return false;return true;}
static float Distance(Vector2 p){float d=float.MaxValue;for(int i=0;i<hull.Count;i++){var a=hull[i];var e=hull[(i+1)%hull.Count]-a;var q=a+e*Mathf.Clamp01(Vector2.Dot(p-a,e)/e.sqrMagnitude);d=Mathf.Min(d,Vector2.Distance(p,q));}return d;}
static bool Coast(float x,float z)=>z<=cutZ&&!Inside(new Vector2(x,z))&&Distance(new Vector2(x,z))<160;
static float Noise(float x,float z,float scale,float seed)=>Mathf.PerlinNoise(x/scale+seed,z/scale+seed*.71f);
static float H(float x,float z){float d=Distance(new Vector2(x,z));float end=Mathf.SmoothStep(0,1,Mathf.Clamp01((cutZ-z)/90));float rise=Mathf.SmoothStep(0,1,Mathf.InverseLerp(5,29,d));float fall=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(55,124,d));float ridge=1-Mathf.Abs(Noise(x,z,38,31)*2-1);float broad=Noise(x,z,135,13);float rocky=Noise(x,z,9,19)-.5f;float peak=(20+broad*32+ridge*14+rocky*5)*rise*fall*end;float shore=Mathf.Lerp(27.5f,23.9f,Mathf.SmoothStep(0,1,Mathf.InverseLerp(97,145,d)));float y=shore+peak;var cell=new Vector2Int(Mathf.RoundToInt(x/4),Mathf.RoundToInt(z/4));for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)if(roads.TryGetValue(cell+new Vector2Int(a,b),out float road))y=Mathf.Min(y,road-1.2f);return Mathf.Max(1,y);}
static void RasterRoads(MeshRenderer[] renderers){foreach(var r in renderers.Where(r=>r.GetComponent<MeshFilter>()&&r.sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name=="City PNG Markings")))){var d=Read(r.GetComponent<MeshFilter>().sharedMesh);var points=Field<Vector3[]>(d,"p").Select(r.transform.TransformPoint).ToArray();var ids=Field<int[]>(d,"ids");for(int i=0;i<ids.Length;i+=3){var a=points[ids[i]];var b=points[ids[i+1]];var c=points[ids[i+2]];if(Inside(new Vector2(a.x,a.z))&&Inside(new Vector2(b.x,b.z))&&Inside(new Vector2(c.x,c.z)))continue;var av=new Vector2(a.x,a.z);var bv=new Vector2(b.x,b.z);var cv=new Vector2(c.x,c.z);float den=Cross(av,bv,cv);if(Mathf.Abs(den)<.01f)continue;for(int z=Mathf.CeilToInt(Mathf.Min(a.z,Mathf.Min(b.z,c.z))/4);z<=Mathf.FloorToInt(Mathf.Max(a.z,Mathf.Max(b.z,c.z))/4);z++)for(int x=Mathf.CeilToInt(Mathf.Min(a.x,Mathf.Min(b.x,c.x))/4);x<=Mathf.FloorToInt(Mathf.Max(a.x,Mathf.Max(b.x,c.x))/4);x++){var q=new Vector2(x*4,z*4);if(!Coast(q.x,q.y))continue;float u=Cross(q,bv,cv)/den,v=Cross(av,q,cv)/den,w=1-u-v;if(u<-.001f||v<-.001f||w<-.001f)continue;float y=a.y*u+b.y*v+c.y*w;var key=new Vector2Int(x,z);if(!roads.TryGetValue(key,out float old)||y<old)roads[key]=y;}}}}
struct Vertex{public Vector3 p,n;public Vector2 uv;public Vertex(Vector3 p,Vector3 n,Vector2 uv){this.p=p;this.n=n;this.uv=uv;}}
static List<Vertex> Clip(List<Vertex> p,Func<Vector3,float> dist,bool keepPositive){var r=new List<Vertex>();if(p.Count<3)return r;var a=p.Last();float da=dist(a.p)*(keepPositive?1:-1);foreach(var b in p){float db=dist(b.p)*(keepPositive?1:-1);if((da>=0)!=(db>=0)){float t=da/(da-db);r.Add(new Vertex(Vector3.Lerp(a.p,b.p,t),Vector3.Lerp(a.n,b.n,t),Vector2.Lerp(a.uv,b.uv,t)));}if(db>=0)r.Add(b);a=b;da=db;}return r;}
static void Fan(List<Vertex> p,List<Vertex> output){for(int i=1;i<p.Count-1;i++)if(Vector3.Cross(p[i].p-p[0].p,p[i+1].p-p[0].p).sqrMagnitude>.000001f)output.AddRange(new[]{p[0],p[i],p[i+1]});}
static Mesh ReplaceApron(MeshFilter f){var d=Read(f.sharedMesh);var points=Field<Vector3[]>(d,"p");var normals=Field<Vector3[]>(d,"normal");var uv=Field<Vector2[][]>(d,"uv")[0];var ids=Field<int[]>(d,"ids");var output=new List<Vertex>();for(int i=0;i<ids.Length;i+=3){var inside=new List<Vertex>();for(int k=0;k<3;k++){int v=ids[i+k];inside.Add(new Vertex(f.transform.TransformPoint(points[v]),normals[v],uv[v]));}for(int edge=0;edge<hull.Count&&inside.Count>=3;edge++){var a=hull[edge];var b=hull[(edge+1)%hull.Count];Func<Vector3,float> dist=p=>Cross(a,b,new Vector2(p.x,p.z));var outside=Clip(inside,dist,false);outside=Clip(outside,p=>p.z-cutZ,true);Fan(outside,output);inside=Clip(inside,dist,true);}Fan(inside,output);}
var m=new Mesh{name="Original shore with coastal terrain apron opening",indexFormat=IndexFormat.UInt32};m.SetVertices(output.Select(v=>f.transform.InverseTransformPoint(v.p)).ToList());m.SetNormals(output.Select(v=>v.n).ToList());m.SetUVs(0,output.Select(v=>v.uv).ToList());m.SetTriangles(Enumerable.Range(0,output.Count).ToArray(),0);m.RecalculateBounds();m.RecalculateTangents();AssetDatabase.CreateAsset(m,Dir+"/Preserved Island Shore.asset");return m;}
static void ConfigureTexture(string path){var t=(TextureImporter)AssetImporter.GetAtPath(path);t.wrapMode=TextureWrapMode.Repeat;t.mipmapEnabled=true;t.streamingMipmaps=true;t.filterMode=FilterMode.Trilinear;t.anisoLevel=4;t.maxTextureSize=2048;t.isReadable=false;foreach(string platform in new[]{"Android","iPhone"})t.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=85});t.SaveAndReimport();}
static TerrainLayer Layer(string name,Texture2D texture,float tile){var l=new TerrainLayer{name=name,diffuseTexture=texture,tileSize=new Vector2(tile,tile),metallic=0,smoothness=.08f};AssetDatabase.CreateAsset(l,Dir+"/"+name+".terrainlayer");return l;}
static void Photo(Scene s,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{s,p,target,name});
static void Run(){var log=new StringBuilder();GameObject group=null;try{
var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!s.isLoaded)throw new Exception("Target scene not loaded");if(s.GetRootGameObjects().Any(g=>g.name=="Coastal Rocky Terrain"))throw new Exception("Coastal terrain already installed");
var root=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");var ring=root.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="polySurface677");var d=Read(ring.sharedMesh);var world=Field<Vector3[]>(d,"p").Select(ring.transform.TransformPoint).ToArray();hull=Hull(world.Select(p=>new Vector2(p.x,p.z)));cutZ=hull.Max(p=>p.y)-65;
string backup="FinalEnvironmentRoadBackup/BeforeCoastalTerrain-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(s,backup+"/Scene.unity",true);string prefabPath=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(root);File.Copy(prefabPath,backup+"/Roads.prefab");
var roadMeshes=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name=="City PNG Markings"))).ToDictionary(f=>f,f=>f.sharedMesh);var renderers=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();RasterRoads(renderers);
var controller=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=controller.IsNight;Vector3 center=new Vector3((hull.Min(p=>p.x)+hull.Max(p=>p.x))/2,27,(hull.Min(p=>p.y)+hull.Max(p=>p.y))/2);var camera=center+new Vector3(-1060,1240,-1280);
try{controller.ApplyDay();Photo(s,camera,center,"Coastal-Terrain-Before");}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}
ConfigureTexture(Dir+"/Seamless Coastal Grey Rock.png");var rock=Layer("Coastal Grey Rock",AssetDatabase.LoadAssetAtPath<Texture2D>(Dir+"/Seamless Coastal Grey Rock.png"),7);var grass=Layer("Coastal Grass",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Road/Grass.jpg"),8);
var shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");if(!shader)throw new Exception("URP terrain shader unavailable");var mat=new Material(shader){name="Mobile Coastal Terrain",enableInstancing=true};mat.EnableKeyword("_TERRAIN_INSTANCED_PERPIXEL_NORMAL");AssetDatabase.CreateAsset(mat,Dir+"/Mobile Coastal Terrain.mat");
float minX=hull.Min(p=>p.x)-170,minZ=hull.Min(p=>p.y)-170;float extent=Mathf.Max(hull.Max(p=>p.x)-minX+170,hull.Max(p=>p.y)-minZ+170);float tile=Mathf.Ceil(extent/64)*32;group=new GameObject("Coastal Rocky Terrain");SceneManager.MoveGameObjectToScene(group,s);var terrains=new Terrain[2,2];float highest=0;int activeCells=0;
for(int tz=0;tz<2;tz++)for(int tx=0;tx<2;tx++){float x0=minX+tx*tile,z0=minZ+tz*tile;const int res=257;var data=new TerrainData{name="Coastal Terrain "+tx+" "+tz,heightmapResolution=res,alphamapResolution=256,baseMapResolution=512,size=new Vector3(tile,110,tile),terrainLayers=new[]{rock,grass}};var heights=new float[res,res];var holes=new bool[res-1,res-1];for(int z=0;z<res;z++)for(int x=0;x<res;x++){float wx=x0+x/(float)(res-1)*tile,wz=z0+z/(float)(res-1)*tile;float h=H(wx,wz);highest=Mathf.Max(highest,h);heights[z,x]=h/110;}data.SetHeights(0,0,heights);
for(int z=0;z<res-1;z++)for(int x=0;x<res-1;x++){float wx=x0+(x+.5f)/(res-1)*tile,wz=z0+(z+.5f)/(res-1)*tile;holes[z,x]=Coast(wx,wz);if(holes[z,x])activeCells++;}data.SetHoles(0,0,holes);
var alpha=new float[256,256,2];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float wx=x0+(x+.5f)/256*tile,wz=z0+(z+.5f)/256*tile;float slope=new Vector2(H(wx+2,wz)-H(wx-2,wz),H(wx,wz+2)-H(wx,wz-2)).magnitude/4;float grassWeight=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.45f,1.1f,slope)))*Mathf.Lerp(.2f,.78f,Noise(wx,wz,22,47));if(H(wx,wz)<27)grassWeight*=.2f;alpha[z,x,1]=grassWeight;alpha[z,x,0]=1-grassWeight;}data.SetAlphamaps(0,0,alpha);AssetDatabase.CreateAsset(data,Dir+"/Terrain "+tx+" "+tz+".asset");var go=Terrain.CreateTerrainGameObject(data);go.name="Rocky Coast "+tx+" "+tz;go.transform.SetParent(group.transform,false);go.transform.position=new Vector3(x0,0,z0);var terrain=go.GetComponent<Terrain>();terrain.materialTemplate=mat;terrain.drawInstanced=true;terrain.heightmapPixelError=10;terrain.heightmapMaximumLOD=1;terrain.basemapDistance=450;terrain.treeDistance=0;terrain.detailObjectDistance=0;terrain.drawTreesAndFoliage=false;terrain.shadowCastingMode=ShadowCastingMode.On;terrain.allowAutoConnect=false;terrain.groupingID=701;terrains[tx,tz]=terrain;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);}
for(int z=0;z<2;z++)for(int x=0;x<2;x++)terrains[x,z].SetNeighbors(x>0?terrains[x-1,z]:null,z<1?terrains[x,z+1]:null,x<1?terrains[x+1,z]:null,z>0?terrains[x,z-1]:null);
var apron=root.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Outer_MEsh");var shore=ReplaceApron(apron);apron.sharedMesh=shore;foreach(var col in apron.GetComponents<MeshCollider>())col.sharedMesh=shore;PrefabUtility.RecordPrefabInstancePropertyModifications(apron);
var pref=PrefabUtility.LoadPrefabContents(prefabPath);try{var f=pref.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name=="Outer_MEsh");f.sharedMesh=shore;foreach(var col in f.GetComponents<MeshCollider>())col.sharedMesh=shore;PrefabUtility.SaveAsPrefabAsset(pref,prefabPath,out bool ok);if(!ok)throw new Exception("Road prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(pref);}
if(roadMeshes.Any(v=>v.Key.sharedMesh!=v.Value))throw new Exception("Road meshes changed");PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);
Physics.SyncTransforms();int checkedRoads=0;foreach(var road in roads){var p=new Vector3(road.Key.x*4,road.Value,road.Key.y*4);foreach(var terrain in terrains){var pos=terrain.transform.position;var size=terrain.terrainData.size;if(p.x<pos.x||p.x>pos.x+size.x||p.z<pos.z||p.z>pos.z+size.z)continue;if(terrain.SampleHeight(p)>p.y-.2f)throw new Exception("Terrain intrudes into existing road "+p);checkedRoads++;}}
try{controller.ApplyDay();Photo(s,camera,center,"Coastal-Terrain-Overview");Photo(s,center+new Vector3(-760,380,-780),center+new Vector3(-200,30,-460),"Coastal-Terrain-Roadside");}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);
log.AppendLine("SUCCESS: 4 editable Unity Terrain tiles; heightmaps 257; maximumLOD=1; pixelError=10; 2 shared terrain layers; one terrain material; GPU instancing; ASTC6x6 rock texture with mip streaming; no terrain trees/details; native terrain colliders; active coastal cells="+activeCells+"; highest sculpted point="+highest+"m; native road meshes preserved="+roadMeshes.Count+"; road clearance samples="+checkedRoads+"; no added roads/port/buildings; original shore retained inside city and on north side; scene/terrain prefab/road prefab saved; backup="+backup);File.WriteAllLines(Dir+"/Coastal Boundary.txt",hull.Select(p=>p.ToString("F3")));}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalTerrainBuildReport.txt",log.ToString());}}
